"""LaTeX tables for the regime map, generated only from stored CSV/JSON in results/regime_map/."""
import csv,json
R='results/regime_map/'
ab=lambda v:{'equivalent':'eq.','first better':'P2 better','second better':'other better','INCONCLUSIVE':'inc.'}[v]
sg=lambda s:s.replace('-','$-$') if s.startswith('-') else '+'+s if not s.startswith('+') else s
fmt=lambda x,d=3:('$-$' if float(x)<0 else '+')+f'{abs(float(x)):.{d}f}'
P={nm:{(x['regime'],x['setting'],x['difference']):x for x in csv.DictReader(open(R+f'{nm}_prediction_paired.csv'))} for nm in('case9','case39')}
C={nm:{(x['regime'],x['authority'],x['difference']):x for x in csv.DictReader(open(R+f'{nm}_closed_loop_paired.csv'))} for nm in('case9','case39')}
S={nm:{(x['regime'],x['authority'],x['controller']):x for x in csv.DictReader(open(R+f'{nm}_closed_loop_summary.csv'))} for nm in('case9','case39')}
M=json.load(open(R+'case9_closed_loop_meta.json')),json.load(open(R+'case39_closed_loop_meta.json'))
L=['% generated by tools/make_regime_tables.py from results/regime_map/*.csv','\\begin{tabular}{llcccc}','\\toprule',
 'Mismatch & Setting & \\multicolumn{2}{c}{case9 (8 runs)} & \\multicolumn{2}{c}{case39 (5 runs)}\\\\','\\cmidrule(lr){3-4}\\cmidrule(lr){5-6}',' & & P2$-$P1c & verdict & P2$-$P1c & verdict\\\\','\\midrule']
rows=[('M0','a','M0 baseline plant','identify'),('M1','a','M1 saliency $\\times2.5$','identify'),('M1','b','','deployment'),('M2','a','M2 load lag $3$\\,s','identify'),('M2','b','','deployment')]
for g,s,lab,sl in rows:
    c=[P[n][(g,s,'P2-P1c')] for n in('case9','case39')]
    L.append(f"{lab} & {sl} & {fmt(c[0]['mean'])} & {ab(c[0]['verdict(margin 0.02)'])} & {fmt(c[1]['mean'])} & {ab(c[1]['verdict(margin 0.02)'])}\\\\")
L+=['\\bottomrule','\\end{tabular}','%%%','\\begin{tabular}{llcccccc}','\\toprule',
 'Mismatch & Authority & \\multicolumn{3}{c}{case9 (6 runs)} & \\multicolumn{3}{c}{case39 (4 runs)}\\\\','\\cmidrule(lr){3-5}\\cmidrule(lr){6-8}',
 ' & & P2 vs P1* & P2 vs C0eq & $E_{\\rm P2}/E_{\\rm C0eq}$ & P2 vs P1* & P2 vs C0eq & $E_{\\rm P2}/E_{\\rm C0eq}$\\\\','\\midrule']
for g,lab in(('M0','M0'),('M1','M1 $\\times2.5$')):
    for a in('1','3'):
        cells=[]
        for n in('case9','case39'):
            p=C[n][(g,a,'P2-P1*')]; q=C[n][(g,a,'P2-C0eq')]; cells+=[ab(p['verdict']),ab(q['verdict']),f"{float(q['energy_ratio']):.2f}"]
        L.append(f"{lab if a=='1' else ''} & $\\times${a} & "+' & '.join(cells)+'\\\\')
L+=['\\bottomrule','\\end{tabular}']
open(R+'regime_main_tables.tex','w').write('\n'.join(L)+'\n')
# supplement
T=['% generated by tools/make_regime_tables.py','\\begin{table}[H]\\centering\\small',
 '\\caption{Regime map, prediction (Protocol): paired difference of the per-run RMSE ratio to A0, P2 minus P1c (P1$^*$ was P1c in every cell), Student-$t$ 95\\% interval, margin $0.02$. Setting: identify = refit in the regime, deployment = baseline-trained coefficients frozen. P3$-$P2 is also shown.}','\\label{tab:S:regpred}',
 '\\resizebox{\\textwidth}{!}{\\begin{tabular}{lllccccl}','\\toprule','Case & Mismatch & Setting & Difference & $n$ & mean & 95\\% interval & verdict\\\\','\\midrule']
for n in('case9','case39'):
    for x in csv.DictReader(open(R+f'{n}_prediction_paired.csv')):
        T.append(f"{n} & {x['regime']} & {'identify' if x['setting']=='a' else 'deployment'} & {x['difference'].replace('-','$-$')} & {x['n']} & {fmt(x['mean'],4)} & [{fmt(x['ci_lo'],4)}, {fmt(x['ci_hi'],4)}] & {ab(x['verdict(margin 0.02)'])}\\\\")
T+=['\\bottomrule','\\end{tabular}}','\\end{table}','',
 '\\begin{table}[H]\\centering\\small','\\caption{Regime map, closed loop: mean over realizations (seed 6001) of RMS speed deviation $w_{\\rm rms}$, input energy $E$, saturation fraction (share of samples with $|u_i|\\ge0.999\\,u_{\\max}$ of that cell) and peak angle (degrees). Violation integrals were zero in all runs.}','\\label{tab:S:regcl}',
 '\\resizebox{\\textwidth}{!}{\\begin{tabular}{lllcccccc}','\\toprule','Case & Mismatch & Authority & Controller & $w_{\\rm rms}$ & $E$ & saturation & peak\\\\','\\midrule']
for n in('case9','case39'):
    for g in('M0','M1'):
        for a in('1','3'):
            for k in('C0','A0','P2','P1*','P3','C0eq'):
                x=S[n][(g,a,k)]; T.append(f"{n} & {g} & $\\times${a} & {k.replace('*','$^*$')} & {float(x['w_rms']):.4f} & {float(x['input_energy']):.2f} & {float(x['saturation_fraction']):.3f} & {float(x['peak_deg']):.2f}\\\\")
T+=['\\bottomrule','\\end{tabular}}','\\end{table}','',
 '\\begin{longtable}{lllcccccl}','\\caption{Regime map, closed loop: paired differences of $w_{\\rm rms}$ (first minus second), Student-$t$ 95\\% interval, margin $0.02\\,\\overline{w}_{\\rm rms,P1^*}$ of the cell, and ratio of mean input energies (first over second).}\\label{tab:S:regclp}\\\\','\\toprule','Case & Mismatch & Authority & Difference & $n$ & mean & 95\\% interval & margin & verdict, $E$-ratio\\\\','\\midrule','\\endfirsthead']
for n in('case9','case39'):
    for x in csv.DictReader(open(R+f'{n}_closed_loop_paired.csv')):
        T.append(f"{n} & {x['regime']} & $\\times${x['authority']} & {x['difference'].replace('*','$^*$')} & {x['n']} & {float(x['mean']):.2e} & [{float(x['ci_lo']):.2e}, {float(x['ci_hi']):.2e}] & {float(x['margin(2% mean P1* w_rms)']):.4f} & {ab(x['verdict'])}, {float(x['energy_ratio']):.3f}\\\\")
T+=['\\bottomrule','\\end{longtable}','',
 '\\begin{table}[H]\\centering\\small','\\caption{Pilot calibration of the gain-matched static law C0eq (seed 80000, 10 pilot runs per cell, 16-step log bisection between $0.05$ and $60$ times $D$). At the upper limit the energy match is not reached.}','\\label{tab:S:regc0eq}',
 '\\begin{tabular}{llccccc}','\\toprule','Case & Cell & gain ($\\times D$) & pilot $E_{\\rm P2}$ & pilot $E_{\\rm C0eq}$ & at upper limit\\\\','\\midrule']
for n,m in zip(('case9','case39'),M):
    for k,v in m['cells'].items(): T.append(f"{n} & {k.replace('_x',' $\\times$')} & {v['gain_multiple_of_D']:.3f} & {v['pilot_energy_P2']:.3f} & {v['pilot_energy_C0eq']:.3f} & {'no' if v['bracket_reached'] else 'yes'}\\\\")
T+=['\\bottomrule','\\end{tabular}','\\end{table}']
open(R+'supp_regime_tables.tex','w').write('\n'.join(T)+'\n')
